$ErrorActionPreference='Stop';$WarningPreference='SilentlyContinue';$cli=Join-Path $PSScriptRoot 'Invoke-MayaQaWorkflow.ps1';$module=Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1';Import-Module $module -Force -WarningAction SilentlyContinue
$dry=& powershell -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $cli -Operation qa-dashboard -StoreRoot 'unused' -TaskId 'unused' -WorkflowId 'unused' -QaWorkflowId create-levels -DryRun 2>$null|ConvertFrom-Json;if($dry.SideEffectsPerformed -or $dry.SelectedWorkflowId -ne 'create-levels'){throw 'Dashboard dry-run safety mismatch.'};if(@($dry.Catalog).Count -ne 6){throw 'Dashboard catalog missing.'}
$bad=$false;try{Get-MayaQaDashboard 'unused' 'unused' 'unused' 'create-plan-views' -DryRun|Out-Null}catch{$bad=$true};if(!$bad){throw 'Unsupported dashboard workflow accepted.'};$text=Get-Content $module -Raw;foreach($name in 'HashVerification','ReceiptStatus','CoordinatorRunId','NativeRunId','QaApprovalStatus','QaPlanStatus'){if($text -notmatch $name){throw "Dashboard field missing: $name"}};'Maya QA dashboard checks passed: 10'
